import heapq

def seatOfArrival(n, k):
    if k == 1:
        return 0
    heap = [(-(n - 1), n - 1, 0, -1)]  # (-distance, seat, left, right); right == -1 marks the tail
    seat = 0

    def push(l, r):
        if r - l >= 2:
            s = (l + r) // 2
            heapq.heappush(heap, (-(s - l), s, l, r))

    for _ in range(k - 1):
        d, seat, l, r = heapq.heappop(heap)
        if r == -1:
            push(l, seat)
        else:
            push(l, seat)
            push(seat, r)
    return seat
